export default [{"w":"acquisition","pos":"noun","def":"the act of one company buying another company or part of it","defId":"tindakan suatu perusahaan membeli perusahaan lain atau sebagiannya","ex":"The acquisition gave the group access to new technology.","exId":"Akuisisi itu memberi grup tersebut akses ke teknologi baru.","colloc":["make an acquisition","recent acquisition","acquisition deal"],"theme":"business"},{"w":"advertising","pos":"noun","def":"the business of creating notices and images to persuade people to buy products","defId":"bisnis membuat pengumuman dan gambar untuk membujuk orang membeli produk","ex":"The company spends millions on advertising every year.","exId":"Perusahaan itu menghabiskan jutaan untuk periklanan setiap tahun.","colloc":["online advertising","advertising budget","advertising campaign"],"theme":"business"},{"w":"agile","pos":"adjective","def":"describing a flexible working method based on quick, incremental development and adaptation","defId":"menggambarkan metode kerja fleksibel berbasis pengembangan cepat dan bertahap","ex":"Adopting an agile approach let the team ship features faster and respond to change.","exId":"Menerapkan pendekatan tangkas memungkinkan tim merilis fitur lebih cepat dan menanggapi perubahan.","colloc":["agile methodology","agile approach","agile team"],"theme":"business"},{"w":"amortisation","pos":"noun","def":"the gradual reduction of a debt, or the spreading of an asset's cost over time","defId":"amortisasi; pengurangan utang secara bertahap atau pembebanan biaya aset sepanjang waktu","ex":"The loan's amortisation is spread evenly over ten years.","exId":"Amortisasi pinjaman itu dibagi rata selama sepuluh tahun.","colloc":["amortisation schedule","debt amortisation"],"theme":"business"},{"w":"annual report","pos":"noun","def":"a yearly document that summarises a company's activities and financial performance","defId":"laporan tahunan; dokumen tahunan yang merangkum kegiatan dan kinerja keuangan perusahaan","ex":"Shareholders reviewed the annual report before the general meeting.","exId":"Para pemegang saham menelaah laporan tahunan sebelum rapat umum.","colloc":["publish an annual report","annual report and accounts"],"theme":"business"},{"w":"attrition","pos":"noun","def":"the gradual loss of employees or customers over time","defId":"atrisi; kehilangan karyawan atau pelanggan secara bertahap seiring waktu","ex":"The company reduced its workforce through natural attrition rather than layoffs.","exId":"Perusahaan mengurangi tenaga kerjanya melalui atrisi alami alih-alih pemutusan hubungan kerja.","colloc":["staff attrition","attrition rate","natural attrition"],"theme":"business"},{"w":"audit","pos":"noun","def":"an official inspection of a company's accounts, usually by an independent body","defId":"audit; pemeriksaan resmi atas pembukuan perusahaan, biasanya oleh pihak independen","ex":"The annual audit revealed several irregularities in the accounts.","exId":"Audit tahunan itu mengungkap sejumlah kejanggalan dalam pembukuan.","colloc":["conduct an audit","internal audit","financial audit"],"theme":"business"},{"w":"backorder","pos":"noun","def":"an order for a product that cannot be filled immediately because it is out of stock","defId":"pesanan barang yang belum bisa dipenuhi karena stok habis","ex":"The popular model sold out so fast that most customers were placed on backorder for weeks.","exId":"Model populer itu terjual habis begitu cepat sehingga sebagian besar pelanggan masuk daftar tunggu pesanan selama berminggu-minggu.","colloc":["on backorder","clear the backorder","backorder queue"],"theme":"business"},{"w":"balance sheet","pos":"noun","def":"a financial statement showing a company's assets, liabilities and capital at a given time","defId":"neraca; laporan keuangan yang menunjukkan aset, kewajiban, dan modal perusahaan pada waktu tertentu","ex":"A strong balance sheet reassured investors about the firm's stability.","exId":"Neraca yang kuat meyakinkan para investor tentang kestabilan perusahaan.","colloc":["strong balance sheet","balance sheet total"],"theme":"business"},{"w":"board of directors","pos":"noun","def":"the group of people elected to oversee and make major decisions for a company","defId":"dewan direksi; sekelompok orang yang dipilih untuk mengawasi dan membuat keputusan besar bagi perusahaan","ex":"The board of directors voted to appoint a new chief executive.","exId":"Dewan direksi memberikan suara untuk mengangkat direktur utama yang baru.","colloc":["sit on the board of directors","board of directors meeting"],"theme":"business"},{"w":"bonus","pos":"noun","def":"an extra sum of money paid to an employee in addition to their normal salary","defId":"bonus; sejumlah uang tambahan yang dibayarkan kepada karyawan di luar gaji biasa","ex":"Staff received a generous year-end bonus after record profits.","exId":"Para karyawan menerima bonus akhir tahun yang besar setelah laba mencetak rekor.","colloc":["performance bonus","year-end bonus","sign-on bonus"],"theme":"business"},{"w":"bootstrap","pos":"verb","def":"to start and grow a business using only personal or internal funds, without outside investment","defId":"memulai dan mengembangkan bisnis hanya dengan dana pribadi atau internal tanpa investasi luar","ex":"They chose to bootstrap the company rather than give away equity to investors.","exId":"Mereka memilih membiayai sendiri perusahaan itu daripada melepas saham kepada investor.","colloc":["bootstrap a startup","bootstrap the business","bootstrapped company"],"theme":"business"},{"w":"brand","pos":"noun","def":"a type of product made by a particular company, identified by its name and image","defId":"jenis produk yang dibuat oleh perusahaan tertentu, dikenali dari nama dan citranya","ex":"Consumers often pay more for a well-known brand they trust.","exId":"Konsumen sering membayar lebih untuk merek terkenal yang mereka percayai.","colloc":["well-known brand","build a brand","brand loyalty"],"theme":"business"},{"w":"branding","pos":"noun","def":"the activity of creating a distinctive name and image for a product to attract customers","defId":"kegiatan menciptakan nama dan citra khas bagi suatu produk untuk menarik pelanggan","ex":"Clever branding turned an ordinary drink into a luxury product.","exId":"Penjenamaan yang cerdik mengubah minuman biasa menjadi produk mewah.","colloc":["strong branding","corporate branding","branding strategy"],"theme":"business"},{"w":"break-even","pos":"noun","def":"the point at which income exactly equals costs, so there is neither profit nor loss","defId":"titik ketika pendapatan tepat sama dengan biaya, sehingga tidak ada untung maupun rugi","ex":"The restaurant reached break-even after just six months of trading.","exId":"Restoran itu mencapai titik impas hanya setelah enam bulan beroperasi.","colloc":["reach break-even","break-even point","break-even analysis"],"theme":"business"},{"w":"buyout","pos":"noun","def":"the purchase of a controlling share of, or the whole of, a company","defId":"pengambilalihan (buyout); pembelian saham pengendali atau keseluruhan sebuah perusahaan","ex":"The management team financed a buyout of the struggling company.","exId":"Tim manajemen mendanai pengambilalihan perusahaan yang sedang kesulitan itu.","colloc":["management buyout","leveraged buyout"],"theme":"business"},{"w":"campaign","pos":"noun","def":"a planned series of activities designed to achieve a particular commercial aim","defId":"rangkaian kegiatan terencana yang dirancang untuk mencapai tujuan komersial tertentu","ex":"Their latest campaign doubled sales within a month.","exId":"Kampanye terbaru mereka menggandakan penjualan dalam sebulan.","colloc":["advertising campaign","launch a campaign","marketing campaign"],"theme":"business"},{"w":"cartel","pos":"noun","def":"a group of companies that secretly agree to fix prices and limit competition","defId":"kartel; sekelompok perusahaan yang diam-diam bersepakat menetapkan harga dan membatasi persaingan","ex":"Regulators fined the cartel for illegally fixing fuel prices.","exId":"Otoritas menjatuhkan denda kepada kartel itu karena menetapkan harga bahan bakar secara ilegal.","colloc":["price-fixing cartel","break up a cartel"],"theme":"business"},{"w":"cash flow","pos":"noun","def":"the movement of money into and out of a business over a period of time","defId":"pergerakan uang masuk dan keluar dari suatu usaha selama periode tertentu","ex":"Late payments from customers created serious cash flow problems.","exId":"Pembayaran yang terlambat dari pelanggan menimbulkan masalah arus kas yang serius.","colloc":["positive cash flow","cash flow problems","manage cash flow"],"theme":"business"},{"w":"churn","pos":"noun","def":"the rate at which customers stop doing business with a company over a given period","defId":"laju pelanggan berhenti berbisnis dengan suatu perusahaan dalam periode tertentu","ex":"High customer churn forced the subscription service to rethink its pricing.","exId":"Tingginya perputaran pelanggan memaksa layanan langganan itu memikirkan ulang harganya.","colloc":["customer churn","churn rate","reduce churn"],"theme":"business"},{"w":"client","pos":"noun","def":"a person or organisation that pays for the services of a professional or company","defId":"orang atau organisasi yang membayar jasa seorang profesional atau perusahaan","ex":"The law firm lost its biggest client to a rival.","exId":"Kantor hukum itu kehilangan klien terbesarnya ke pesaing.","colloc":["loyal client","client base","meet a client"],"theme":"business"},{"w":"clientele","pos":"noun","def":"all the customers or clients of a business, considered as a group","defId":"seluruh pelanggan atau klien suatu usaha yang dianggap sebagai satu kelompok","ex":"The boutique attracts a wealthy clientele from across the city.","exId":"Butik itu menarik klientele kaya dari seluruh penjuru kota.","colloc":["wealthy clientele","loyal clientele","attract a clientele"],"theme":"business"},{"w":"collateral","pos":"noun","def":"property or assets promised to a lender as security for a loan","defId":"agunan; properti atau aset yang dijanjikan kepada pemberi pinjaman sebagai jaminan atas pinjaman","ex":"The bank required the warehouse as collateral for the business loan.","exId":"Bank meminta gudang itu sebagai agunan untuk pinjaman usaha.","colloc":["put up collateral","loan collateral"],"theme":"business"},{"w":"commerce","pos":"noun","def":"the activity of buying and selling goods and services on a large scale","defId":"kegiatan membeli dan menjual barang serta jasa dalam skala besar","ex":"The city has been a centre of commerce for centuries.","exId":"Kota itu telah menjadi pusat perniagaan selama berabad-abad.","colloc":["international commerce","chamber of commerce","centre of commerce"],"theme":"business"},{"w":"competitor","pos":"noun","def":"a company or person that competes with others in the same market","defId":"pesaing; perusahaan atau orang yang bersaing dengan pihak lain di pasar yang sama","ex":"Their main competitor launched a cheaper version of the same device.","exId":"Pesaing utama mereka meluncurkan versi yang lebih murah dari perangkat yang sama.","colloc":["main competitor","direct competitor","outperform competitors"],"theme":"business"},{"w":"conglomerate","pos":"noun","def":"a large company formed by combining several different businesses","defId":"perusahaan besar yang terbentuk dari penggabungan beberapa bisnis berbeda","ex":"The media conglomerate owns newspapers, radio stations and websites.","exId":"Konglomerat media itu memiliki surat kabar, stasiun radio, dan situs web.","colloc":["media conglomerate","multinational conglomerate","giant conglomerate"],"theme":"business"},{"w":"consumer","pos":"noun","def":"a person who buys goods or services for their own use","defId":"orang yang membeli barang atau jasa untuk dipakai sendiri","ex":"Modern consumers increasingly expect fast, free delivery.","exId":"Konsumen modern semakin mengharapkan pengiriman yang cepat dan gratis.","colloc":["consumer demand","consumer behaviour","average consumer"],"theme":"business"},{"w":"contingency","pos":"noun","def":"a plan or amount of money set aside to deal with unexpected events","defId":"kontingensi; rencana atau dana cadangan yang disiapkan untuk menghadapi kejadian tak terduga","ex":"The budget included a contingency for unexpected building costs.","exId":"Anggaran itu memasukkan dana kontingensi untuk biaya pembangunan yang tak terduga.","colloc":["contingency plan","contingency fund"],"theme":"business"},{"w":"contract","pos":"noun","def":"a formal written or spoken agreement that is legally binding","defId":"kesepakatan resmi secara tertulis atau lisan yang mengikat secara hukum","ex":"Both parties signed the contract before any work began.","exId":"Kedua belah pihak menandatangani kontrak sebelum pekerjaan apa pun dimulai.","colloc":["sign a contract","breach of contract","renew a contract"],"theme":"business"},{"w":"conversion","pos":"noun","def":"the point at which a prospective customer completes a desired action, such as making a purchase","defId":"titik ketika calon pelanggan menyelesaikan tindakan yang diinginkan, seperti melakukan pembelian","ex":"Redesigning the checkout page lifted the site's conversion rate by fifteen percent.","exId":"Mendesain ulang halaman pembayaran menaikkan tingkat konversi situs sebesar lima belas persen.","colloc":["conversion rate","boost conversion","conversion funnel"],"theme":"business"},{"w":"corporate","pos":"adjective","def":"relating to a large company or business organisation","defId":"berkaitan dengan perusahaan atau organisasi bisnis besar","ex":"The firm is trying to improve its corporate image.","exId":"Perusahaan itu berusaha memperbaiki citra korporatnya.","colloc":["corporate image","corporate culture","corporate strategy"],"theme":"business"},{"w":"creditor","pos":"noun","def":"a person or company to whom money is owed","defId":"kreditor; orang atau perusahaan yang berhak menerima pembayaran utang","ex":"The bankrupt firm could not repay its creditors in full.","exId":"Perusahaan yang bangkrut itu tidak mampu melunasi kreditornya sepenuhnya.","colloc":["repay creditors","major creditor"],"theme":"business"},{"w":"cross-sell","pos":"verb","def":"to sell a customer additional related products alongside their main purchase","defId":"menjual produk terkait tambahan kepada pelanggan bersama pembelian utamanya","ex":"The bank tries to cross-sell insurance to everyone who opens a new account.","exId":"Bank itu berusaha menjual silang asuransi kepada setiap orang yang membuka rekening baru.","colloc":["cross-sell products","cross-sell opportunity","cross-sell to customers"],"theme":"business"},{"w":"debtor","pos":"noun","def":"a person or company that owes money to someone else","defId":"debitur; orang atau perusahaan yang berutang kepada pihak lain","ex":"The accounts team chased several debtors for overdue payments.","exId":"Tim akuntansi menagih beberapa debitur atas pembayaran yang telah jatuh tempo.","colloc":["chase debtors","outstanding debtor"],"theme":"business"},{"w":"demand","pos":"noun","def":"the amount of a product or service that customers want to buy","defId":"jumlah suatu produk atau jasa yang ingin dibeli oleh pelanggan","ex":"Demand for electric cars has soared in the past few years.","exId":"Permintaan mobil listrik melonjak dalam beberapa tahun terakhir.","colloc":["high demand","meet demand","demand for"],"theme":"business"},{"w":"disruptor","pos":"noun","def":"a company or product that radically changes an existing market or industry","defId":"disruptor; perusahaan atau produk yang secara radikal mengubah pasar atau industri yang ada","ex":"The ride-hailing app became a major disruptor in the taxi industry.","exId":"Aplikasi transportasi daring itu menjadi disruptor besar dalam industri taksi.","colloc":["market disruptor","industry disruptor"],"theme":"business"},{"w":"distributor","pos":"noun","def":"a person or company that supplies goods to shops and other businesses","defId":"orang atau perusahaan yang memasok barang ke toko dan bisnis lain","ex":"They appointed a local distributor to handle sales across the region.","exId":"Mereka menunjuk distributor lokal untuk menangani penjualan di seluruh wilayah.","colloc":["sole distributor","local distributor","appoint a distributor"],"theme":"business"},{"w":"diversification","pos":"noun","def":"the practice of expanding into new products or markets to reduce risk","defId":"diversifikasi; praktik memperluas ke produk atau pasar baru untuk mengurangi risiko","ex":"Diversification into overseas markets protected the firm from a local downturn.","exId":"Diversifikasi ke pasar luar negeri melindungi perusahaan dari kemerosotan di dalam negeri.","colloc":["product diversification","diversification strategy"],"theme":"business"},{"w":"divestment","pos":"noun","def":"the act of selling off part of a business or its assets","defId":"tindakan menjual sebagian bisnis atau asetnya","ex":"The group announced the divestment of its loss-making retail division to focus on logistics.","exId":"Grup itu mengumumkan pelepasan divisi ritelnya yang merugi untuk fokus pada logistik.","colloc":["divestment of assets","announce a divestment","divestment strategy"],"theme":"business"},{"w":"due diligence","pos":"noun","def":"a careful investigation of a business before signing a deal or making an investment","defId":"uji tuntas (due diligence); penyelidikan cermat atas sebuah usaha sebelum menandatangani kesepakatan atau berinvestasi","ex":"Investors carried out thorough due diligence before buying the company.","exId":"Para investor melakukan uji tuntas menyeluruh sebelum membeli perusahaan itu.","colloc":["carry out due diligence","financial due diligence"],"theme":"business"},{"w":"e-commerce","pos":"noun","def":"the business of buying and selling goods and services on the internet","defId":"bisnis membeli dan menjual barang serta jasa melalui internet","ex":"The shift to e-commerce forced many high-street shops to close.","exId":"Peralihan ke perdagangan elektronik memaksa banyak toko di jalan utama tutup.","colloc":["e-commerce platform","e-commerce site","grow e-commerce"],"theme":"business"},{"w":"enterprise","pos":"noun","def":"a business or company, especially one showing initiative and taking risks","defId":"suatu usaha atau perusahaan, terutama yang menunjukkan inisiatif dan berani mengambil risiko","ex":"The government offers loans to support small enterprises.","exId":"Pemerintah menawarkan pinjaman untuk mendukung usaha-usaha kecil.","colloc":["small enterprise","private enterprise","business enterprise"],"theme":"business"},{"w":"entrepreneurship","pos":"noun","def":"the activity of setting up and running businesses, taking on financial risk to do so","defId":"kewirausahaan; kegiatan mendirikan dan menjalankan usaha sambil menanggung risiko keuangan","ex":"The university runs a course on entrepreneurship for aspiring founders.","exId":"Universitas itu menyelenggarakan mata kuliah kewirausahaan untuk calon pendiri usaha.","colloc":["social entrepreneurship","promote entrepreneurship"],"theme":"business"},{"w":"executive","pos":"noun","def":"a senior manager with the authority to make important decisions in an organisation","defId":"eksekutif; manajer senior yang berwenang mengambil keputusan penting dalam sebuah organisasi","ex":"As a senior executive, she oversees marketing across the entire region.","exId":"Sebagai eksekutif senior, ia mengawasi pemasaran di seluruh wilayah.","colloc":["senior executive","chief executive","executive team"],"theme":"business"},{"w":"expansion","pos":"noun","def":"the process of a business becoming larger by opening in new places or markets","defId":"proses suatu usaha menjadi lebih besar dengan membuka cabang di tempat atau pasar baru","ex":"Rapid expansion into Asia boosted the firm's revenue.","exId":"Ekspansi cepat ke Asia mendongkrak pendapatan perusahaan.","colloc":["rapid expansion","business expansion","plans for expansion"],"theme":"business"},{"w":"flotation","pos":"noun","def":"the process of offering a company's shares for sale on the stock market for the first time","defId":"penawaran saham perdana (flotation); proses menawarkan saham perusahaan untuk pertama kalinya di pasar saham","ex":"The tech firm raised millions through its stock market flotation.","exId":"Perusahaan teknologi itu mengumpulkan jutaan melalui penawaran saham perdananya di bursa.","colloc":["stock market flotation","public flotation"],"theme":"business"},{"w":"franchise","pos":"noun","def":"the right to sell a company's products or services in a particular area using its brand name","defId":"hak untuk menjual produk atau jasa suatu perusahaan di wilayah tertentu dengan menggunakan nama mereknya","ex":"She bought a coffee-shop franchise and opened her first outlet downtown.","exId":"Dia membeli waralaba kedai kopi dan membuka gerai pertamanya di pusat kota.","colloc":["buy a franchise","fast-food franchise","franchise fee"],"theme":"business"},{"w":"fulfilment","pos":"noun","def":"the process of receiving, packing and delivering customer orders","defId":"proses menerima, mengemas, dan mengirim pesanan pelanggan","ex":"The retailer opened a new fulfilment centre to speed up next-day delivery.","exId":"Peritel itu membuka pusat pemenuhan pesanan baru untuk mempercepat pengiriman keesokan hari.","colloc":["order fulfilment","fulfilment centre","fulfilment costs"],"theme":"business"},{"w":"goodwill","pos":"noun","def":"the established reputation and customer loyalty of a business, treated as an intangible asset","defId":"reputasi mapan dan loyalitas pelanggan suatu bisnis yang dianggap aset takberwujud","ex":"Much of the acquisition price reflected the goodwill built up over decades of trading.","exId":"Sebagian besar harga akuisisi mencerminkan goodwill yang terbangun selama puluhan tahun berbisnis.","colloc":["build goodwill","goodwill of a business","goodwill on the balance sheet"],"theme":"business"},{"w":"gross","pos":"adjective","def":"referring to a total amount before any deductions such as tax or expenses","defId":"bruto (kotor); merujuk pada jumlah total sebelum pengurangan seperti pajak atau biaya","ex":"The company reported gross profits of two million pounds before expenses.","exId":"Perusahaan melaporkan laba kotor sebesar dua juta pound sebelum dipotong biaya.","colloc":["gross profit","gross income","gross margin"],"theme":"business"},{"w":"headquarters","pos":"noun","def":"the main offices from which a company or organisation is controlled","defId":"kantor utama tempat suatu perusahaan atau organisasi dikendalikan","ex":"The bank moved its headquarters to a new tower in the city centre.","exId":"Bank itu memindahkan kantor pusatnya ke menara baru di pusat kota.","colloc":["corporate headquarters","move headquarters","global headquarters"],"theme":"business"},{"w":"hedge","pos":"verb","def":"to protect against financial loss by making balancing investments","defId":"melakukan lindung nilai (hedge); melindungi diri dari kerugian finansial dengan investasi penyeimbang","ex":"The airline hedged against rising fuel prices by buying futures contracts.","exId":"Maskapai itu melakukan lindung nilai terhadap kenaikan harga bahan bakar dengan membeli kontrak berjangka.","colloc":["hedge against risk","hedge fund"],"theme":"business"},{"w":"incentivise","pos":"verb","def":"to motivate someone to act in a particular way by offering a reward or advantage","defId":"mendorong seseorang bertindak dengan cara tertentu melalui imbalan atau keuntungan","ex":"The company introduced bonuses to incentivise staff to hit their sales targets.","exId":"Perusahaan memperkenalkan bonus untuk memotivasi staf mencapai target penjualan mereka.","colloc":["incentivise staff","incentivise sales","financially incentivise"],"theme":"business"},{"w":"incubator","pos":"noun","def":"an organisation that helps new startups grow by providing space, funding and advice","defId":"inkubator; organisasi yang membantu perusahaan rintisan berkembang dengan menyediakan ruang, dana, dan bimbingan","ex":"Their startup joined a tech incubator that offered mentoring and office space.","exId":"Perusahaan rintisan mereka bergabung dengan inkubator teknologi yang menawarkan bimbingan dan ruang kantor.","colloc":["business incubator","tech incubator","startup incubator"],"theme":"business"},{"w":"insolvency","pos":"noun","def":"the state of being unable to pay the money that you owe","defId":"keadaan tidak mampu membayar uang yang menjadi utang","ex":"Rising costs pushed the retailer towards insolvency.","exId":"Kenaikan biaya mendorong peritel itu menuju kepailitan.","colloc":["face insolvency","risk of insolvency","insolvency proceedings"],"theme":"business"},{"w":"intermediary","pos":"noun","def":"a person or organisation that acts as a link between two parties in a transaction","defId":"pihak atau organisasi yang menjadi penghubung antara dua pihak dalam suatu transaksi","ex":"The broker serves as an intermediary between buyers and sellers, taking a small commission.","exId":"Pialang itu bertindak sebagai perantara antara pembeli dan penjual dengan mengambil komisi kecil.","colloc":["financial intermediary","act as an intermediary","trusted intermediary"],"theme":"business"},{"w":"investor","pos":"noun","def":"a person or organisation that puts money into a business hoping to make a profit","defId":"orang atau organisasi yang menanamkan uang ke dalam usaha dengan harapan memperoleh keuntungan","ex":"The startup needed to convince investors that its idea would work.","exId":"Perusahaan rintisan itu perlu meyakinkan para investor bahwa idenya akan berhasil.","colloc":["attract investors","foreign investor","private investor"],"theme":"business"},{"w":"iteration","pos":"noun","def":"a repeated version of a product refined through successive rounds of improvement","defId":"versi berulang dari suatu produk yang disempurnakan melalui putaran perbaikan berturut","ex":"Each iteration of the app addressed feedback gathered from the previous release.","exId":"Setiap iterasi aplikasi itu menanggapi masukan yang dikumpulkan dari rilis sebelumnya.","colloc":["next iteration","rapid iteration","product iteration"],"theme":"business"},{"w":"joint venture","pos":"noun","def":"a commercial enterprise undertaken jointly by two companies that otherwise remain independent","defId":"usaha komersial yang dijalankan bersama oleh dua perusahaan yang tetap berdiri sendiri","ex":"The carmaker set up a joint venture with a local firm to gain access to the Asian market.","exId":"Produsen mobil itu membentuk usaha patungan dengan perusahaan lokal untuk memasuki pasar Asia.","colloc":["set up a joint venture","joint venture agreement","50-50 joint venture"],"theme":"business"},{"w":"KPI","pos":"noun","def":"key performance indicator; a measurable value used to track progress towards a goal","defId":"KPI (indikator kinerja utama); nilai terukur yang digunakan untuk memantau kemajuan menuju suatu tujuan","ex":"Customer retention is one of the most important KPIs for the sales team.","exId":"Retensi pelanggan adalah salah satu KPI terpenting bagi tim penjualan.","colloc":["track KPIs","meet a KPI","key KPI"],"theme":"business"},{"w":"lead time","pos":"noun","def":"the amount of time between the start of a process and its completion, such as from order to delivery","defId":"waktu tunggu (lead time); rentang waktu antara dimulainya suatu proses dan penyelesaiannya, misalnya dari pemesanan hingga pengiriman","ex":"Suppliers shortened the lead time from six weeks to just ten days.","exId":"Para pemasok memangkas waktu tunggu dari enam minggu menjadi hanya sepuluh hari.","colloc":["reduce lead time","long lead time"],"theme":"business"},{"w":"leverage","pos":"noun","def":"the use of borrowed money to increase the potential return of an investment","defId":"leverage; penggunaan uang pinjaman untuk meningkatkan potensi imbal hasil investasi","ex":"High leverage made the firm vulnerable when interest rates rose.","exId":"Leverage yang tinggi membuat perusahaan rentan ketika suku bunga naik.","colloc":["financial leverage","high leverage"],"theme":"business"},{"w":"licensing","pos":"noun","def":"the practice of granting official permission to use a product, brand or technology in exchange for a fee","defId":"pemberian izin resmi untuk memakai produk, merek, atau teknologi dengan imbalan biaya","ex":"The studio earns millions through licensing its characters to toy manufacturers.","exId":"Studio itu meraup jutaan melalui pemberian lisensi karakternya kepada produsen mainan.","colloc":["licensing agreement","licensing fee","brand licensing"],"theme":"business"},{"w":"liquidate","pos":"verb","def":"to close a business and sell its assets to pay its debts","defId":"menutup suatu usaha dan menjual asetnya untuk membayar utang","ex":"The owners were forced to liquidate the firm after heavy losses.","exId":"Para pemilik terpaksa melikuidasi perusahaan setelah kerugian besar.","colloc":["liquidate a company","liquidate assets","forced to liquidate"],"theme":"business"},{"w":"logistics","pos":"noun","def":"the practical organisation of moving, storing and delivering goods and materials","defId":"pengaturan praktis dalam memindahkan, menyimpan, dan mengirimkan barang serta bahan","ex":"Poor logistics meant the parcels arrived two weeks late.","exId":"Logistik yang buruk membuat paket-paket itu tiba dua minggu terlambat.","colloc":["logistics company","handle the logistics","logistics network"],"theme":"business"},{"w":"loss leader","pos":"noun","def":"a product sold at a loss to attract customers who will then buy other profitable goods","defId":"produk yang dijual rugi untuk menarik pelanggan agar membeli barang lain yang menguntungkan","ex":"The supermarket uses cheap milk as a loss leader to draw shoppers through the doors.","exId":"Supermarket itu memakai susu murah sebagai umpan rugi untuk menarik pembeli masuk.","colloc":["use as a loss leader","loss-leader pricing","classic loss leader"],"theme":"business"},{"w":"margin","pos":"noun","def":"the difference between the cost of producing something and the price it sells for","defId":"margin; selisih antara biaya produksi sesuatu dan harga jualnya","ex":"Rising material costs squeezed the company's margin on every unit sold.","exId":"Kenaikan biaya bahan baku menekan margin perusahaan pada setiap unit yang terjual.","colloc":["profit margin","narrow margin","gross margin"],"theme":"business"},{"w":"market leader","pos":"noun","def":"the company that sells the most of a particular product or service in a market","defId":"pemimpin pasar; perusahaan yang menjual produk atau jasa tertentu paling banyak di suatu pasar","ex":"The brand remained the market leader despite fierce competition from newcomers.","exId":"Merek itu tetap menjadi pemimpin pasar meski persaingan sengit dari pendatang baru.","colloc":["become the market leader","clear market leader"],"theme":"business"},{"w":"market share","pos":"noun","def":"the portion of total sales in a market that one company controls","defId":"bagian dari total penjualan di suatu pasar yang dikuasai oleh satu perusahaan","ex":"By cutting prices, the firm doubled its market share in a year.","exId":"Dengan memangkas harga, perusahaan itu melipatgandakan pangsa pasarnya dalam setahun.","colloc":["gain market share","lose market share","large market share"],"theme":"business"},{"w":"marketing","pos":"noun","def":"the activity of promoting and selling products, including research and advertising","defId":"kegiatan mempromosikan dan menjual produk, termasuk riset dan periklanan","ex":"A strong marketing team helped the brand reach younger buyers.","exId":"Tim pemasaran yang kuat membantu merek itu menjangkau pembeli yang lebih muda.","colloc":["marketing campaign","digital marketing","marketing strategy"],"theme":"business"},{"w":"merchandise","pos":"noun","def":"goods that are bought and sold, especially in shops","defId":"barang yang dibeli dan dijual, terutama di toko","ex":"The band sells branded merchandise at every concert.","exId":"Band itu menjual barang dagangan bermerek di setiap konser.","colloc":["branded merchandise","sell merchandise","official merchandise"],"theme":"business"},{"w":"metric","pos":"noun","def":"a standard of measurement used to assess business performance","defId":"metrik; standar pengukuran yang digunakan untuk menilai kinerja bisnis","ex":"Website traffic is a useful metric for judging a campaign's success.","exId":"Lalu lintas situs web adalah metrik yang berguna untuk menilai keberhasilan sebuah kampanye.","colloc":["key metric","performance metric","track metrics"],"theme":"business"},{"w":"middleman","pos":"noun","def":"a person or business that buys goods from producers and sells them to retailers or consumers","defId":"orang atau usaha yang membeli barang dari produsen lalu menjualnya ke peritel atau konsumen","ex":"By selling directly online, the brand cut out the middleman and lowered its prices.","exId":"Dengan menjual langsung secara daring, merek itu memangkas perantara dan menurunkan harganya.","colloc":["cut out the middleman","act as a middleman","middleman fees"],"theme":"business"},{"w":"negotiation","pos":"noun","def":"formal discussion aimed at reaching an agreement on price, terms or conditions","defId":"pembahasan resmi untuk mencapai kesepakatan mengenai harga atau syarat","ex":"After months of tough negotiation, the two sides finally agreed on the contract terms.","exId":"Setelah berbulan-bulan negosiasi alot, kedua pihak akhirnya menyepakati ketentuan kontrak.","colloc":["contract negotiation","enter negotiation","break off negotiation"],"theme":"business"},{"w":"niche","pos":"noun","def":"a small, specialised area of the market for a particular product or service","defId":"bagian pasar yang kecil dan khusus untuk produk atau jasa tertentu","ex":"The company found a profitable niche selling handmade shoes online.","exId":"Perusahaan itu menemukan ceruk pasar yang menguntungkan dengan menjual sepatu buatan tangan secara daring.","colloc":["niche market","find a niche","niche product"],"theme":"business"},{"w":"oligopoly","pos":"noun","def":"a market that is controlled by a small number of large companies","defId":"oligopoli; pasar yang dikuasai oleh sejumlah kecil perusahaan besar","ex":"The telecoms sector is an oligopoly dominated by just three providers.","exId":"Sektor telekomunikasi merupakan oligopoli yang didominasi hanya oleh tiga penyedia.","colloc":["form an oligopoly","market oligopoly"],"theme":"business"},{"w":"outbid","pos":"verb","def":"to offer a higher price than someone else, especially in an auction or tender","defId":"menawar dengan harga lebih tinggi daripada orang lain, terutama dalam lelang atau tender","ex":"A larger conglomerate outbid us for the contract by offering a lower unit cost.","exId":"Sebuah konglomerat yang lebih besar mengalahkan tawaran kami untuk kontrak itu dengan menawarkan biaya per unit lebih rendah.","colloc":["outbid a rival","outbid competitors","be outbid"],"theme":"business"},{"w":"outreach","pos":"noun","def":"an organisation's activity of contacting and engaging potential customers or communities","defId":"kegiatan organisasi menghubungi dan merangkul calon pelanggan atau komunitas","ex":"The firm's outreach to small businesses helped it win a whole new segment of clients.","exId":"Jangkauan perusahaan itu kepada usaha kecil membantunya meraih segmen klien yang benar-benar baru.","colloc":["customer outreach","outreach programme","community outreach"],"theme":"business"},{"w":"partnership","pos":"noun","def":"a formal business arrangement in which two or more parties share ownership, risks and profits","defId":"kesepakatan bisnis formal di mana dua pihak atau lebih berbagi kepemilikan, risiko, dan laba","ex":"The two firms entered a strategic partnership to develop the new payment platform together.","exId":"Kedua perusahaan menjalin kemitraan strategis untuk bersama-sama mengembangkan platform pembayaran baru.","colloc":["strategic partnership","enter a partnership","business partnership"],"theme":"business"},{"w":"patent","pos":"noun","def":"an official right that stops others from copying or selling your invention","defId":"hak resmi yang mencegah orang lain menyalin atau menjual penemuanmu","ex":"The company filed a patent to protect its new engine design.","exId":"Perusahaan itu mengajukan paten untuk melindungi desain mesin barunya.","colloc":["file a patent","hold a patent","patent application"],"theme":"business"},{"w":"pilot scheme","pos":"noun","def":"a small-scale trial run of a project used to test its feasibility before full launch","defId":"uji coba proyek berskala kecil untuk menguji kelayakan sebelum peluncuran penuh","ex":"Before the nationwide launch, the retailer ran a pilot scheme in three cities.","exId":"Sebelum peluncuran nasional, peritel itu menjalankan skema percontohan di tiga kota.","colloc":["run a pilot scheme","pilot scheme results","launch a pilot scheme"],"theme":"business"},{"w":"pivot","pos":"verb","def":"to change a business's strategy or direction significantly in response to the market","defId":"mengubah strategi atau arah bisnis secara signifikan menyesuaikan pasar","ex":"When demand for hardware collapsed, the founders decided to pivot to selling software services instead.","exId":"Ketika permintaan perangkat keras anjlok, para pendiri memutuskan beralih total ke penjualan layanan perangkat lunak.","colloc":["pivot to","strategic pivot","pivot the business"],"theme":"business"},{"w":"positioning","pos":"noun","def":"the way a company shapes how its brand or product is perceived relative to competitors","defId":"cara perusahaan membentuk persepsi merek atau produknya dibandingkan pesaing","ex":"Clever brand positioning made the drink seem more premium than its rivals.","exId":"Penempatan merek yang cerdas membuat minuman itu terkesan lebih premium daripada pesaingnya.","colloc":["brand positioning","market positioning","positioning strategy"],"theme":"business"},{"w":"profit margin","pos":"noun","def":"the difference between the cost of making something and the price it is sold for","defId":"selisih antara biaya membuat sesuatu dan harga jualnya","ex":"Supermarkets often survive on very thin profit margins.","exId":"Supermarket sering bertahan dengan margin keuntungan yang sangat tipis.","colloc":["thin profit margin","increase the profit margin","healthy profit margin"],"theme":"business"},{"w":"profitability","pos":"noun","def":"the degree to which a business produces a financial gain","defId":"tingkat sejauh mana suatu usaha menghasilkan keuntungan finansial","ex":"Cutting waste greatly improved the factory's profitability.","exId":"Mengurangi pemborosan sangat meningkatkan profitabilitas pabrik itu.","colloc":["improve profitability","long-term profitability","boost profitability"],"theme":"business"},{"w":"projection","pos":"noun","def":"an estimate of future figures such as sales or profits based on current data","defId":"proyeksi; perkiraan angka masa depan seperti penjualan atau laba berdasarkan data saat ini","ex":"Their sales projection for next year looks overly optimistic.","exId":"Proyeksi penjualan mereka untuk tahun depan tampak terlalu optimis.","colloc":["sales projection","financial projection","revenue projection"],"theme":"business"},{"w":"proposal","pos":"noun","def":"a formal written plan or suggestion put forward for consideration by others","defId":"rencana atau usulan tertulis resmi yang diajukan untuk dipertimbangkan","ex":"She submitted a detailed proposal outlining how the merger would cut operating costs.","exId":"Ia mengajukan proposal rinci yang menguraikan bagaimana merger itu akan memangkas biaya operasional.","colloc":["submit a proposal","business proposal","reject a proposal"],"theme":"business"},{"w":"quarterly","pos":"adjective","def":"happening or produced once every three months","defId":"triwulanan; terjadi atau dibuat setiap tiga bulan sekali","ex":"The company publishes its quarterly earnings at the end of each three-month period.","exId":"Perusahaan menerbitkan laba triwulanannya pada akhir setiap periode tiga bulan.","colloc":["quarterly report","quarterly earnings","quarterly results"],"theme":"business"},{"w":"rebate","pos":"noun","def":"a partial refund given to a customer as a reduction on the amount paid","defId":"pengembalian sebagian uang kepada pelanggan sebagai potongan dari jumlah yang dibayar","ex":"Buyers who purchase before June qualify for a fifty-dollar rebate on the appliance.","exId":"Pembeli yang membeli sebelum Juni berhak atas rabat lima puluh dolar untuk peralatan itu.","colloc":["cash rebate","offer a rebate","claim a rebate"],"theme":"business"},{"w":"rebrand","pos":"verb","def":"to change the image, name or identity of a company or product","defId":"mengubah citra, nama, atau identitas suatu perusahaan atau produk","ex":"The airline decided to rebrand after years of poor customer reviews.","exId":"Maskapai itu memutuskan mengubah merek setelah bertahun-tahun ulasan pelanggan buruk.","colloc":["rebrand the company","completely rebrand","rebrand as"],"theme":"business"},{"w":"receivership","pos":"noun","def":"the situation in which a company is run by an appointed official because it cannot pay its debts","defId":"receivership (kepailitan dengan kurator); kondisi ketika perusahaan dikelola oleh pihak yang ditunjuk karena tidak mampu membayar utang","ex":"The retailer went into receivership after failing to secure new funding.","exId":"Peritel itu masuk ke dalam receivership setelah gagal memperoleh pendanaan baru.","colloc":["go into receivership","placed in receivership"],"theme":"business"},{"w":"reshuffle","pos":"noun","def":"a reorganisation in which people or roles within a company are moved around","defId":"penataan ulang di mana orang atau jabatan dalam perusahaan dipindah-pindahkan","ex":"A boardroom reshuffle brought in a new chief executive to steer the turnaround.","exId":"Perombakan jajaran direksi mendatangkan direktur utama baru untuk memimpin pemulihan.","colloc":["management reshuffle","boardroom reshuffle","major reshuffle"],"theme":"business"},{"w":"restructure","pos":"verb","def":"to organise a company in a new way to make it more efficient","defId":"menata ulang suatu perusahaan dengan cara baru agar lebih efisien","ex":"Management decided to restructure the whole sales division.","exId":"Manajemen memutuskan untuk merestrukturisasi seluruh divisi penjualan.","colloc":["restructure the company","restructure debt","fully restructure"],"theme":"business"},{"w":"retail","pos":"noun","def":"the sale of goods to the public in small quantities for their own use","defId":"penjualan barang kepada masyarakat dalam jumlah kecil untuk pemakaian sendiri","ex":"After years in retail, she understood exactly what shoppers wanted.","exId":"Setelah bertahun-tahun di bidang ritel, dia benar-benar memahami apa yang diinginkan para pembeli.","colloc":["retail sales","retail price","work in retail"],"theme":"business"},{"w":"roadmap","pos":"noun","def":"a strategic plan that sets out goals and the steps needed to achieve them over time","defId":"rencana strategis yang menetapkan tujuan dan langkah untuk mencapainya seiring waktu","ex":"The board approved a three-year roadmap for expanding into overseas markets.","exId":"Dewan menyetujui peta jalan tiga tahun untuk berekspansi ke pasar luar negeri.","colloc":["strategic roadmap","product roadmap","lay out a roadmap"],"theme":"business"},{"w":"scalable","pos":"adjective","def":"able to grow or handle a much larger amount of work without major problems","defId":"mampu tumbuh atau menangani beban kerja yang jauh lebih besar tanpa masalah berarti","ex":"Investors love a scalable business that can expand cheaply.","exId":"Investor menyukai bisnis yang dapat diskalakan dan bisa berkembang dengan biaya murah.","colloc":["scalable business","scalable model","highly scalable"],"theme":"business"},{"w":"scale-up","pos":"noun","def":"a company that has moved beyond the startup stage and is growing rapidly","defId":"scale-up; perusahaan yang telah melewati tahap rintisan dan sedang tumbuh dengan pesat","ex":"The fintech scale-up doubled its workforce within a single year.","exId":"Perusahaan fintech scale-up itu menggandakan jumlah karyawannya hanya dalam setahun.","colloc":["fast-growing scale-up","scale-up phase"],"theme":"business"},{"w":"segmentation","pos":"noun","def":"the division of a market into distinct groups of customers with similar needs","defId":"segmentasi; pembagian pasar menjadi kelompok-kelompok pelanggan berbeda dengan kebutuhan serupa","ex":"Market segmentation helped the brand target younger buyers more effectively.","exId":"Segmentasi pasar membantu merek itu menyasar pembeli yang lebih muda secara lebih efektif.","colloc":["market segmentation","customer segmentation"],"theme":"business"},{"w":"solvency","pos":"noun","def":"the ability of a company to meet its long-term debts and financial obligations","defId":"solvabilitas; kemampuan perusahaan melunasi utang dan kewajiban keuangan jangka panjangnya","ex":"Auditors questioned the firm's solvency after it reported three years of losses.","exId":"Para auditor mempertanyakan solvabilitas perusahaan setelah melaporkan kerugian selama tiga tahun.","colloc":["long-term solvency","solvency test","financial solvency"],"theme":"business"},{"w":"sponsorship","pos":"noun","def":"financial support given to an event or team in return for advertising","defId":"dukungan finansial yang diberikan kepada suatu acara atau tim sebagai imbalan atas iklan","ex":"The football club relies heavily on corporate sponsorship.","exId":"Klub sepak bola itu sangat bergantung pada sponsor perusahaan.","colloc":["corporate sponsorship","sponsorship deal","secure sponsorship"],"theme":"business"},{"w":"startup","pos":"noun","def":"a newly established business, especially a small one in its early stages","defId":"perusahaan rintisan, terutama yang masih kecil dan berada di tahap awal","ex":"Their tech startup grew from three friends into a company of two hundred employees.","exId":"Perusahaan rintisan teknologi mereka berkembang dari tiga sahabat menjadi perusahaan berisi dua ratus karyawan.","colloc":["tech startup","launch a startup","startup founder"],"theme":"business"},{"w":"stockpile","pos":"verb","def":"to accumulate and store a large reserve of goods or materials for future use","defId":"menimbun dan menyimpan cadangan barang atau bahan dalam jumlah besar","ex":"Manufacturers began to stockpile components ahead of the expected supply shortage.","exId":"Para produsen mulai menimbun komponen menjelang kelangkaan pasokan yang diperkirakan.","colloc":["stockpile goods","stockpile inventory","build up a stockpile"],"theme":"business"},{"w":"stocktaking","pos":"noun","def":"the process of counting and recording all the goods a business currently holds","defId":"proses menghitung dan mencatat semua barang yang saat ini dimiliki suatu usaha","ex":"The shop closes early once a month for stocktaking to reconcile its inventory.","exId":"Toko itu tutup lebih awal sebulan sekali untuk penghitungan stok guna mencocokkan persediaannya.","colloc":["annual stocktaking","carry out stocktaking","stocktaking exercise"],"theme":"business"},{"w":"subsidiary","pos":"noun","def":"a company that is owned or controlled by another, larger company","defId":"perusahaan yang dimiliki atau dikendalikan oleh perusahaan lain yang lebih besar","ex":"The bank runs its insurance business through a separate subsidiary.","exId":"Bank itu menjalankan bisnis asuransinya melalui anak perusahaan terpisah.","colloc":["wholly-owned subsidiary","overseas subsidiary","set up a subsidiary"],"theme":"business"},{"w":"supplier","pos":"noun","def":"a company or person that provides goods or materials to a business","defId":"perusahaan atau orang yang menyediakan barang atau bahan bagi suatu usaha","ex":"The factory switched to a cheaper supplier to reduce costs.","exId":"Pabrik itu beralih ke pemasok yang lebih murah untuk mengurangi biaya.","colloc":["main supplier","reliable supplier","change suppliers"],"theme":"business"},{"w":"supply chain","pos":"noun","def":"the whole system of people, resources and steps involved in producing and delivering a product","defId":"seluruh sistem orang, sumber daya, dan tahapan yang terlibat dalam memproduksi dan mengirimkan suatu produk","ex":"The pandemic disrupted the global supply chain for months.","exId":"Pandemi mengganggu rantai pasok global selama berbulan-bulan.","colloc":["global supply chain","supply chain disruption","manage the supply chain"],"theme":"business"},{"w":"takeover","pos":"noun","def":"an act of gaining control of a company by buying most of its shares","defId":"tindakan mengambil alih kendali suatu perusahaan dengan membeli sebagian besar sahamnya","ex":"Shareholders rejected the hostile takeover bid.","exId":"Para pemegang saham menolak tawaran pengambilalihan paksa itu.","colloc":["hostile takeover","takeover bid","takeover target"],"theme":"business"},{"w":"target market","pos":"noun","def":"the particular group of customers a product is aimed at","defId":"kelompok pelanggan tertentu yang menjadi sasaran suatu produk","ex":"Teenagers are the main target market for the new game.","exId":"Remaja adalah target pasar utama untuk gim baru itu.","colloc":["identify a target market","main target market","reach the target market"],"theme":"business"},{"w":"tender","pos":"noun","def":"a formal written offer to supply goods or do work for an agreed price","defId":"penawaran tertulis resmi untuk memasok barang atau melakukan pekerjaan dengan harga yang disepakati","ex":"Five construction firms submitted a tender for the new bridge.","exId":"Lima perusahaan konstruksi mengajukan tender untuk jembatan baru itu.","colloc":["submit a tender","win a tender","competitive tender"],"theme":"business"},{"w":"testimonial","pos":"noun","def":"a formal written or spoken statement praising a product or service, used in marketing","defId":"pernyataan tertulis atau lisan yang memuji produk atau jasa, dipakai untuk pemasaran","ex":"The website features glowing testimonials from satisfied clients to build trust.","exId":"Situs web itu menampilkan testimoni memuji dari klien yang puas untuk membangun kepercayaan.","colloc":["customer testimonial","glowing testimonial","testimonial page"],"theme":"business"},{"w":"trademark","pos":"noun","def":"a name or symbol legally registered to identify a company's products","defId":"nama atau simbol yang terdaftar secara hukum untuk menandai produk suatu perusahaan","ex":"The logo is a registered trademark that competitors cannot use.","exId":"Logo itu adalah merek dagang terdaftar yang tidak boleh dipakai pesaing.","colloc":["registered trademark","trademark infringement","register a trademark"],"theme":"business"},{"w":"turnaround","pos":"noun","def":"a significant improvement in the fortunes of a struggling company","defId":"pemulihan (turnaround); perbaikan signifikan atas kondisi perusahaan yang sedang kesulitan","ex":"The new CEO engineered a remarkable turnaround within two years.","exId":"Direktur utama yang baru merancang pemulihan luar biasa dalam dua tahun.","colloc":["turnaround plan","business turnaround","turnaround time"],"theme":"business"},{"w":"undercut","pos":"verb","def":"to sell goods or services more cheaply than a competitor in order to win business","defId":"menjual barang atau jasa lebih murah dari pesaing untuk merebut pasar","ex":"The new entrant managed to undercut established rivals by pricing its plans 20% lower.","exId":"Pendatang baru itu berhasil menjual lebih murah dari pesaing mapan dengan harga paket 20% lebih rendah.","colloc":["undercut competitors","undercut the price","undercut rivals"],"theme":"business"},{"w":"underwrite","pos":"verb","def":"to accept financial responsibility for a risk, or to guarantee the sale of shares","defId":"menjamin (underwrite); menanggung tanggung jawab finansial atas suatu risiko atau menjamin penjualan saham","ex":"A group of banks agreed to underwrite the company's share offering.","exId":"Sekelompok bank sepakat menjamin penawaran saham perusahaan itu.","colloc":["underwrite a loan","underwrite an offering"],"theme":"business"},{"w":"unicorn","pos":"noun","def":"a privately held startup company valued at more than one billion dollars","defId":"perusahaan rintisan swasta yang bernilai lebih dari satu miliar dolar","ex":"Within five years the app became a unicorn, reaching a valuation of two billion dollars.","exId":"Dalam lima tahun aplikasi itu menjadi unicorn dengan valuasi mencapai dua miliar dolar.","colloc":["tech unicorn","become a unicorn","unicorn startup"],"theme":"business"},{"w":"upscale","pos":"adjective","def":"aimed at wealthier customers and offering higher quality or luxury","defId":"ditujukan untuk pelanggan kelas atas; mewah dan berkualitas tinggi","ex":"The chain repositioned itself as an upscale brand to attract higher-spending shoppers.","exId":"Jaringan itu memposisikan ulang dirinya sebagai merek kelas atas untuk menarik pembeli berdaya beli tinggi.","colloc":["upscale market","upscale brand","go upscale"],"theme":"business"},{"w":"upsell","pos":"verb","def":"to persuade a customer to buy a more expensive item or upgrade at the point of sale","defId":"membujuk pelanggan membeli barang lebih mahal atau peningkatan saat transaksi","ex":"Staff are trained to upsell customers to the premium package whenever possible.","exId":"Staf dilatih untuk menawarkan paket premium yang lebih mahal kepada pelanggan bila memungkinkan.","colloc":["upsell customers","upsell to premium","upsell technique"],"theme":"business"},{"w":"valuation","pos":"noun","def":"an estimate of how much a company or asset is worth","defId":"valuasi (penilaian); perkiraan seberapa besar nilai suatu perusahaan atau aset","ex":"The startup achieved a valuation of one billion dollars after its latest funding round.","exId":"Perusahaan rintisan itu mencapai valuasi satu miliar dolar setelah putaran pendanaan terakhirnya.","colloc":["company valuation","market valuation"],"theme":"business"},{"w":"vendor","pos":"noun","def":"a person or company that sells a particular product or service","defId":"orang atau perusahaan yang menjual produk atau jasa tertentu","ex":"The company works with several software vendors.","exId":"Perusahaan itu bekerja sama dengan beberapa vendor perangkat lunak.","colloc":["street vendor","software vendor","approved vendor"],"theme":"business"},{"w":"warehouse","pos":"noun","def":"a large building where goods are stored before being sold or distributed","defId":"bangunan besar tempat barang disimpan sebelum dijual atau didistribusikan","ex":"The online retailer built a huge warehouse near the motorway.","exId":"Peritel daring itu membangun gudang besar di dekat jalan tol.","colloc":["storage warehouse","warehouse space","distribution warehouse"],"theme":"business"},{"w":"warranty","pos":"noun","def":"a written promise to repair or replace a product if it develops a fault","defId":"janji tertulis untuk memperbaiki atau mengganti produk jika mengalami kerusakan","ex":"The laptop comes with a two-year warranty.","exId":"Laptop itu dilengkapi garansi dua tahun.","colloc":["under warranty","extended warranty","warranty period"],"theme":"business"},{"w":"wholesale","pos":"noun","def":"the selling of goods in large quantities at low prices, usually to shops rather than the public","defId":"penjualan barang dalam jumlah besar dengan harga murah, biasanya kepada toko dan bukan kepada masyarakat umum","ex":"The bakery buys its flour wholesale to keep costs down.","exId":"Toko roti itu membeli tepungnya secara grosir untuk menekan biaya.","colloc":["buy wholesale","wholesale price","wholesale market"],"theme":"business"},{"w":"word-of-mouth","pos":"noun","def":"the informal spread of information or recommendation from one person to another","defId":"penyebaran informasi atau rekomendasi secara informal dari orang ke orang","ex":"The restaurant grew purely through word-of-mouth, without spending a penny on advertising.","exId":"Restoran itu berkembang murni dari mulut ke mulut, tanpa mengeluarkan sepeser pun untuk iklan.","colloc":["word-of-mouth marketing","spread by word-of-mouth","positive word-of-mouth"],"theme":"business"}];
